css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .56); position: relative; }
.loader .base { position: absolute; bottom: 10%; left: 4%; width: 92%; height: 18%; border-radius: 4px; background: linear-gradient(#64748b, #1e293b); }
.loader .arm { position: absolute; bottom: 30%; left: 4%; width: 92%; height: 21%; border-radius: 5px 8px 8px 5px; background: linear-gradient(var(--accent-2), var(--accent)); transform-origin: 3% 100%; animation: staple-press calc(var(--loader-speed) * 1.3) cubic-bezier(.5, 0, .3, 1) infinite; }
.loader i { position: absolute; bottom: 27%; right: 14%; width: 8%; height: 9%; border-top: 3px solid var(--accent-2); border-left: 3px solid var(--accent-2); border-right: 3px solid var(--accent-2); border-radius: 2px 2px 0 0; opacity: 0; animation: staple-pop calc(var(--loader-speed) * 1.3) ease-out infinite; }
@keyframes staple-press { 0%, 100% { transform: rotate(-13deg); } 45%, 58% { transform: rotate(0deg); } }
@keyframes staple-pop { 0%, 42% { opacity: 0; transform: translateY(-60%); } 52%, 82% { opacity: 1; transform: translateY(0); } 100% { opacity: 0; transform: translateY(0); } }
